:root {
  color-scheme: dark;
  --bg: #0f172a;
  --bg2: #111c38;
  --panel: rgba(17, 24, 39, 0.84);
  --panel-strong: rgba(8, 12, 24, 0.96);
  --border: rgba(148, 163, 184, 0.18);
  --text: #e5eefc;
  --muted: #9fb1d1;
  --accent: #7dd3fc;
  --accent-strong: #38bdf8;
  --good: #34d399;
  --warn: #fbbf24;
  --bad: #fb7185;
  --cell-empty: #172554;
  --cell-shadow: rgba(0, 0, 0, 0.35);
}

* { box-sizing: border-box; }
html, body { min-height: 100%; }
body {
  margin: 0;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: radial-gradient(circle at top, #1e293b, var(--bg));
  color: var(--text);
}
button, input, select, textarea { font: inherit; }
button {
  border: 0;
  border-radius: 999px;
  padding: 0.8rem 1rem;
  cursor: pointer;
  color: var(--text);
  background: rgba(148, 163, 184, 0.16);
  transition: transform 140ms ease, background 140ms ease, box-shadow 140ms ease, opacity 140ms ease;
}
button:hover:not(:disabled) { transform: translateY(-1px); background: rgba(148, 163, 184, 0.26); }
button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
button:disabled { cursor: not-allowed; opacity: 0.55; }
.primary { background: linear-gradient(135deg, var(--accent-strong), #0ea5e9); color: #02121f; font-weight: 700; }
.primary:hover:not(:disabled) { background: linear-gradient(135deg, #67e8f9, var(--accent-strong)); }
.secondary { background: rgba(59, 130, 246, 0.12); border: 1px solid rgba(125, 211, 252, 0.2); }
.hidden { display: none !important; }
.page-shell { max-width: 1450px; margin: 0 auto; padding: 1rem; }
.topbar {
  display: flex; justify-content: space-between; gap: 1rem; align-items: center;
  margin-bottom: 1rem; padding: 1rem 1.2rem; border: 1px solid var(--border);
  background: rgba(15, 23, 42, 0.78); backdrop-filter: blur(16px); border-radius: 24px;
  box-shadow: 0 20px 60px rgba(2, 6, 23, 0.35);
}
.eyebrow { text-transform: uppercase; letter-spacing: 0.16em; font-size: 0.72rem; color: var(--muted); margin: 0 0 0.35rem; }
.topbar h1, .panel h2 { margin: 0; line-height: 1.1; }
.topbar-actions { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; justify-content: flex-end; }
.session-badge, .revision-pill {
  border: 1px solid rgba(125, 211, 252, 0.22); background: rgba(8, 15, 34, 0.86); border-radius: 999px; padding: 0.55rem 0.9rem; color: var(--accent);
}
.app-grid, .dashboard { display: grid; gap: 1rem; }
.panel, .card {
  border: 1px solid var(--border); background: var(--panel); backdrop-filter: blur(16px);
  border-radius: 24px; box-shadow: 0 20px 48px rgba(2, 6, 23, 0.3);
}
.panel { padding: 1.1rem; }
.panel-heading, .status-grid, .archive-layout, .analysis-layout, .game-layout { display: grid; gap: 1rem; }
.panel-heading { grid-template-columns: 1fr auto; align-items: start; margin-bottom: 1rem; }
.panel-actions, .row-actions { display: flex; gap: 0.7rem; flex-wrap: wrap; align-items: center; }
.status-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.scoreline { font-size: 1.2rem; font-weight: 700; margin-bottom: 0.2rem; }
.muted { color: var(--muted); }
.message-bar { min-height: 2rem; padding: 0.35rem 0.6rem; color: var(--accent); }
.auth-panel { max-width: 540px; margin: 0 auto; }
.form-grid { display: grid; gap: 0.9rem; }
.form-grid.compact { grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: end; }
label { display: grid; gap: 0.35rem; }
label span { font-size: 0.92rem; color: var(--muted); }
input, select {
  width: 100%; border-radius: 16px; border: 1px solid rgba(148, 163, 184, 0.24);
  padding: 0.8rem 0.95rem; color: var(--text); background: rgba(15, 23, 42, 0.9);
}
.demo-card, .side-card, .card {
  border: 1px solid rgba(148, 163, 184, 0.12); background: rgba(15, 23, 42, 0.82);
  border-radius: 20px; padding: 1rem;
}
.game-layout { grid-template-columns: minmax(0, 1fr) 300px; align-items: start; }
.archive-layout { grid-template-columns: minmax(0, 1.05fr) 0.95fr; }
.analysis-layout { grid-template-columns: minmax(0, 1.05fr) 0.95fr; align-items: start; }
.subgrid { margin-top: 1rem; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
.history-list { margin: 0.5rem 0 0; padding-left: 1.2rem; display: grid; gap: 0.35rem; }
.muted-list { color: var(--muted); }
.board-shell { display: grid; gap: 0.6rem; }
.column-row { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 0.45rem; }
.board-grid {
  display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 0.45rem; padding: 0.8rem;
  border-radius: 24px; background: linear-gradient(180deg, #0b4a7a, #0a2f57); box-shadow: inset 0 0 0 1px rgba(255,255,255,0.08);
}
.cell {
  aspect-ratio: 1; border-radius: 999px; background: var(--cell-empty); box-shadow: inset 0 3px 6px var(--cell-shadow);
  border: 1px solid rgba(255,255,255,0.07); position: relative; min-width: 0;
}
.cell.red { background: radial-gradient(circle at 35% 35%, #fda4af, #e11d48 62%, #881337 100%); }
.cell.yellow { background: radial-gradient(circle at 35% 35%, #fef08a, #f59e0b 60%, #92400e 100%); }
.cell.win { box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.9), inset 0 3px 6px var(--cell-shadow); }
.cell.diff { outline: 3px dashed #fbbf24; outline-offset: -3px; }
.board-title { display: flex; justify-content: space-between; gap: 1rem; align-items: center; }
.result-line { min-height: 1.4rem; color: var(--accent); }
.tree { display: grid; gap: 0.35rem; font-size: 0.95rem; }
.tree-node { border-left: 2px solid rgba(148, 163, 184, 0.24); padding-left: 0.8rem; margin-left: 0.2rem; }
.tree-node.selected { border-left-color: var(--accent); }
.tree button { width: 100%; text-align: left; border-radius: 14px; }
.node-meta { color: var(--muted); font-size: 0.88rem; }
.analysis-list { display: grid; gap: 0.75rem; }
.analysis-item { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 0.75rem; align-items: center; }
.analysis-item .muted { font-size: 0.9rem; }
.redo-choice { display: flex; gap: 0.5rem; align-items: center; }
.redo-choice select { max-width: 280px; }
.archive-board { margin: 0.8rem 0; }
.toast {
  position: fixed; left: 50%; bottom: 1rem; transform: translateX(-50%);
  background: rgba(15, 23, 42, 0.95); color: var(--text); border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 999px; padding: 0.8rem 1rem; box-shadow: 0 18px 42px rgba(2, 6, 23, 0.35);
  max-width: min(92vw, 920px); text-align: center; pointer-events: none; opacity: 0; transition: opacity 160ms ease;
}
.toast.show { opacity: 1; }
.toast.good { color: var(--good); }
.toast.warn { color: var(--warn); }
.toast.bad { color: var(--bad); }
.small-note { font-size: 0.9rem; color: var(--muted); }
.inline-stack { display: grid; gap: 0.5rem; }
.compare-grid { display: grid; gap: 0.8rem; }
.compare-cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.8rem; }
.compare-card { border: 1px solid rgba(148, 163, 184, 0.12); border-radius: 18px; padding: 0.8rem; background: rgba(2, 6, 23, 0.24); }
.compare-diff { color: var(--warn); }
@media (max-width: 1100px) {
  .status-grid, .game-layout, .archive-layout, .analysis-layout, .subgrid { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  .topbar { flex-direction: column; align-items: flex-start; }
  .form-grid.compact, .compare-cols, .analysis-item { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}

