function req(method, path, body, token) { return new Promise((resolve, reject) => { const data = body ? JSON.stringify(body) : ''; const options = { hostname:'127.0.0.1', port:3000, method, path, headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(data), ...(token?{Authorization:`Bearer ${token}`}:{})}}; const r = http.request(options, res => { let buf=''; res.on('data', d => buf += d); res.on('end', () => resolve({status: res.statusCode, body: buf})); }); r.on('error', reject); if (data) r.write(data); r.end(); }); }
(async()=>{ const login = JSON.parse((await req('POST','/api/auth/login',{email:'avery@dropline.test',password:'password123'})).body); const logout = await req('POST','/api/auth/logout-all',{}, login.token); const bootstrap = await req('GET','/api/bootstrap', null, login.token); console.log('logout', logout.status, logout.body); console.log('bootstrap after logout', bootstrap.status, bootstrap.body); })();
